import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        System.out.print("Enter recorded vehicle speed (km/h): ");
        int speed = scanner.nextInt();

        int speedLimit = 80;

        System.out.println("Radar check complete.");

        // Single conditional guard:
        if (speed > speedLimit) {
            int over = speed - speedLimit;
            System.out.println("ALERT: Speed limit exceeded by " + over + " km/h!");
            System.out.println("Fine issued: Rs 2000");
        }

        System.out.println("Drive safely!");
        scanner.close();
    }
}

