practiceProblems.solutionCode:
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int age = scanner.nextInt();
        if (age >= 18) {
            System.out.println("Eligible to vote");
        }
        System.out.println("Voter verification complete");
        scanner.close();
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        double total = scanner.nextDouble();
        if (total >= 500.0) {
            System.out.println("Free shipping applied!");
        }
        System.out.println("Thank you for shopping with us.");
        scanner.close();
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        double balance = scanner.nextDouble();
        if (balance < 1000.0) {
            System.out.println("Warning: Balance below minimum threshold!");
        }
        System.out.printf("Current balance: Rs %.2f%n", balance);
        scanner.close();
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int temp = scanner.nextInt();
        if (temp <= 0) {
            System.out.println("Frost alert: Freezing conditions!");
        }
        System.out.println("Sensor check complete");
        scanner.close();
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int points = scanner.nextInt();
        if (points % 2 == 0) {
            points += 10;
        }
        System.out.println("Final Points: " + points);
        scanner.close();
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String pass = scanner.next();
        if (pass.length() < 8) {
            System.out.println("Warning: Password too short!");
        }
        System.out.println("Length recorded: " + pass.length());
        scanner.close();
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int hours = scanner.nextInt();
        double rate = scanner.nextDouble();
        double total = hours * rate;
        if (hours > 40) {
            total += 500.0;
        }
        System.out.printf("Total Earnings: Rs %.2f%n", total);
        scanner.close();
    }
}

